	if surfaceID == "" {
		return errorResponse(cmd.ID, "invalid_params", "surface_id is required")
	}
	encoded, _ := cmd.Params["image_base64"].(string)
	if encoded == "" {
		return errorResponse(cmd.ID, "invalid_params", "image_base64 is required")
