        Task.detached(priority: .userInitiated) { [weak self] in
            let encoded = ImagePaste.encode(image)
            await MainActor.run {
                guard let self else { return }
                guard let encoded else {
                    self.showImagePasteStatus("Couldn't read that image")
                    return
                }
